// 承認くんの状態遷移を enum で表して、シナリオを流してみる
enum RequestStatus {
    DRAFT, SUBMITTED, APPROVED, RETURNED, WITHDRAWN;

    boolean canTransitionTo(RequestStatus next) {
        return switch (this) {
            case DRAFT -> next == SUBMITTED || next == WITHDRAWN;
            case SUBMITTED -> next == APPROVED || next == RETURNED;
            case RETURNED -> next == SUBMITTED || next == WITHDRAWN;
            case APPROVED, WITHDRAWN -> false;
        };
    }
}

// ここを変えてみよう:並びを入れ替える・WITHDRAWN を途中に入れる・
// SUBMITTED の直後に WITHDRAWN を置く(申請中の取下げ)とどうなる?
List<RequestStatus> scenario = List.of(
        RequestStatus.SUBMITTED,   // ハルが申請
        RequestStatus.RETURNED,    // モカ先輩が差戻し
        RequestStatus.SUBMITTED,   // ハルが直して再申請
        RequestStatus.APPROVED,    // 承認
        RequestStatus.RETURNED);   // 承認後に差戻し……できる?

RequestStatus current = RequestStatus.DRAFT;
System.out.println("スタート: " + current);
for (RequestStatus next : scenario) {
    if (current.canTransitionTo(next)) {
        System.out.println(current + " → " + next + " OK");
        current = next;
    } else {
        System.out.println(current + " → " + next + " できません(状態はそのまま)");
    }
}
System.out.println("最終状態: " + current);

// 業務ルール3「100,000円以上の承認は ADMIN だけ」を2通りに書いて比べる
// ここを変えてみよう:amounts に 100001 や -1 を足す/LIMIT を 50_000 にする
final int LIMIT = 100_000;

boolean wrong(Integer amount) {        // よくある書き間違い
    return amount > LIMIT;             // 「超える」になっている & null で落ちる
}

boolean right(Integer amount) {        // 承認くんの書き方
    return amount != null && amount >= LIMIT;
}

Integer[] amounts = {99_999, 100_000, 120_000, null};   // null は休暇申請
for (Integer a : amounts) {
    String w;
    try {
        w = wrong(a) ? "ADMIN" : "APPROVERでOK";
    } catch (NullPointerException e) {
        w = "NullPointerException!";
    }
    String r = right(a) ? "ADMIN" : "APPROVERでOK";
    System.out.printf("%-8s 間違い版: %-22s 正しい版: %s%n", a, w, r);
}

